actions.script:
def slurper = new groovy.json.JsonSlurper()
questions = questionList.collect { q -> [questionId: q.questionId,
    moduleId: q.moduleId, sequenceNum: q.sequenceNum, question: q.question,
    options: slurper.parseText(q.optionsJson ?: '[]')] }

                def slurper = new groovy.json.JsonSlurper()
                List completed = progressEntity?.completedLessons ?
                    slurper.parseText(progressEntity.completedLessons as String) as List : []
                Map scores = progressEntity?.quizScores ?
                    slurper.parseText(progressEntity.quizScores as String) as Map : [:]
                // the plain rule: first lesson not done in a module that is open
                def ordered = moduleList.collectMany { m -> lessonList.findAll { it.moduleId == m.moduleId } }
                def nextLesson = ordered.find { !(it.lessonId in completed) &&
                    !(states.moduleStates[it.moduleId]?.locked) }
                recommendation = [nextLessonId: nextLesson?.lessonId,
                    reason: nextLesson ? "Next: ${nextLesson.title}".toString() : 'All lessons are done.',
                    reviewLessonIds: []]
                def CourseAiUtil = ec.resource.script("component://growerp/service/course/CourseAiUtil.groovy", null)
                if (!CourseAiUtil.testMode() && completed) {
                    StringBuilder outline = new StringBuilder()
                    for (m in moduleList) {
                        Map st = states.moduleStates[m.moduleId] ?: [:]
                        outline << "Module \"${m.title}\"${st.locked ? ' (locked)' : ''}${st.overdue ? ' (overdue)' : ''}" +
                            "${scores[m.moduleId] != null ? ", quiz score ${scores[m.moduleId]}%" : ''}\n"
                        lessonList.findAll { it.moduleId == m.moduleId }.each { l ->
                            outline << "  [${l.lessonId}] ${l.title}${l.lessonId in completed ? ' - done' : ''}\n" }
                    }
                    String work = submissionList.unique(false) { it.exerciseId }.collect {
                        "exercise ${it.exerciseId}: ${(it.instructorScore ?: it.aiScore) ?: '-'}%" }.join(', ')
                    String prompt = """You are a learning coach. From the progress of a learner in an online course, recommend
the single best next step and the lessons worth reviewing.

COURSE: ${access.courseEntity.title}
OUTLINE (lesson ids in brackets):
${outline}
EXERCISE SCORES: ${work ?: 'none yet'}

RULES:
- nextLessonId: a lesson id from the outline that is not locked; usually the first one not done,
  but a lesson to redo when a quiz score is below 70%.
- reviewLessonIds: at most 3 done lessons of modules with a low quiz or exercise score.
- reason: one or two encouraging sentences to the learner, in the language of the course.

Answer with JSON only: {"nextLessonId": "", "reason": "", "reviewLessonIds": []}"""
                    try {
                        def advice = CourseAiUtil.askJson(ec, access.ownerPartyId, prompt, null)
                        def validIds = ordered.findAll { !(states.moduleStates[it.moduleId]?.locked) }*.lessonId
                        if (advice instanceof Map && advice.nextLessonId in validIds) {
                            recommendation = [nextLessonId: advice.nextLessonId, reason: advice.reason ?: recommendation.reason,
                                reviewLessonIds: (advice.reviewLessonIds ?: []).findAll { it in validIds }.take(3)]
                        }
                    } catch (Exception e) {
                        ec.logger.warn("Course recommendation without AI: ${e.message}")
                        ec.message.clearErrors()
                    }
                }

def scores = progressEntity?.quizScores ?
    new groovy.json.JsonSlurper().parseText(progressEntity.quizScores as String) as Map : [:]
def quizModuleIds = questionList*.moduleId.unique()
def notPassed = quizModuleIds.findAll { ((scores[it] ?: 0) as int) < 70 }
String reason = null
if ((progressEntity?.progressPercent ?: 0) < 100) reason = 'Complete all lessons first'
else if (notPassed) reason = "Pass the quiz of ${notPassed.size()} more module${notPassed.size() == 1 ? '' : 's'} first"

def party = ec.user.userAccount?.partyId ? ec.entity.find("mantle.party.Person")
    .condition("partyId", ec.user.userAccount.partyId).one() : null
def company = ec.entity.find("mantle.party.Organization")
    .condition("partyId", checked.courseEntity.ownerPartyId).one()
// the owner is not always the organization itself: take the company of the owner
if (!company) {
    def related = ec.service.sync().name("growerp.100.GeneralServices100.get#RelatedCompanyAndOwner").call()
    company = ec.entity.find("mantle.party.Organization")
        .condition("partyId", related.companyPartyId).one()
}
certificate = [eligible: reason == null, reason: reason,
    courseId: courseId, courseTitle: checked.courseEntity.title,
    estimatedDuration: checked.courseEntity.estimatedDuration,
    learnerName: [party?.firstName, party?.lastName].findAll { it }.join(' ') ?: ec.user.username,
    companyName: company?.organizationName,
    completedDate: progressEntity?.completedDate,
    certificateNo: reason == null ? "${courseId}-${progressEntity.progressId}" : null]
